/* Checkbox */

.round-checkbox {
  position: relative;
}

.round-checkbox label {
  border-radius: 50%;
  width: 24px;
  height: 24px;
  left: 0;
  top: 0;
  position: absolute;
  cursor: pointer;
  border-width: 1px;
  border-style: solid;
  --tw-border-opacity: 1;
  border-color: rgba(245, 246, 249, var(--tw-border-opacity));
  --tw-bg-opacity: 1;
  background-color: rgba(255, 255, 255, var(--tw-bg-opacity));
}

.round-checkbox label:after {
  content: "";
  width: 11px;
  height: 6px;
  left: 5px;
  top: 7px;
  transform: rotate(-45deg);
  position: absolute;
  border-width: 2px;
  border-top-width: 0px;
  border-right-width: 0px;
  border-style: solid;
  --tw-border-opacity: 1;
  border-color: rgba(255, 255, 255, var(--tw-border-opacity));
  opacity: 0;
}

.round-checkbox input[type="checkbox"] {
  visibility: hidden;
}

.round-checkbox input[type="checkbox"]:checked + label {
  --tw-border-opacity: 1;
  border-color: rgba(0, 96, 225, var(--tw-border-opacity));
  --tw-bg-opacity: 1;
  background-color: rgba(0, 96, 225, var(--tw-bg-opacity));
}

.round-checkbox input[type="checkbox"]:checked + label:after {
  opacity: 1;
}

